import{_ as l}from"./plugin-vue_export-helper-c27b6911.js";import{r as o,o as i,c as d,a,d as n,e as s,w as p,f as t}from"./app-d8a6c058.js";const r={},u=t('<h1 id="运行时内存布局-runtime-memory-layout" tabindex="-1"><a class="header-anchor" href="#运行时内存布局-runtime-memory-layout" aria-hidden="true">#</a> 运行时内存布局（Runtime Memory Layout）</h1><p>运行时内存的布局直接影响着我们如何生成代码、调试程序以及管理对象的生命周期。例如，全局变量的地址如何确定？函数返回后，局部变量为什么不能继续使用？<code>malloc</code> 返回的内存又由谁释放？这些问题都与运行时内存有关。</p><p>现代操作系统通常为每个进程提供独立的<strong>虚拟地址空间</strong>。程序使用的是虚拟地址，由处理器和操作系统共同完成到物理内存的映射。因此，两个进程中数值相同的地址，通常并不指向同一份数据；同一进程中的线程则共享地址空间。</p><p>本文以 <strong>Linux 上采用 ELF 格式的 C/C++ 程序</strong>为主要示例。其他操作系统、处理器和语言运行时的布局可能不同，下面的区域名称、权限和地址顺序也不是语言标准的保证。</p><h2 id="内存布局总览" tabindex="-1"><a class="header-anchor" href="#内存布局总览" aria-hidden="true">#</a> 内存布局总览</h2><p>理解内存布局时，要先区分三个层次：</p><ul><li><strong>ELF 节（section）</strong>：编译器和链接器组织文件内容的单位，例如 <code>.text</code>、<code>.rodata</code>、<code>.data</code>、<code>.bss</code>。</li><li><strong>ELF 加载段（segment）</strong>：加载器根据程序头将内容映射到内存的单位。一个 <code>PT_LOAD</code> 段可以包含多个节，加载器并不是逐节加载程序。</li><li><strong>运行时内存区域</strong>：进程实际拥有的虚拟内存映射，包括可执行文件、堆、栈、共享库和匿名映射等。日常所说的“代码段”“数据段”往往是对这类用途的概括。</li></ul><p>先通过交互图观察各区域：点击区域可查看其内容、权限和生命周期，也可以从下拉框选择具体对象，对照指针本身与所指对象的位置。</p>',8),k=t(`<p>交互图中的顺序只用于建立直观印象，不能据此计算地址。地址空间中还存在未映射的空洞，ASLR（地址空间布局随机化）也会改变各区域的位置。尤其是 64 位系统，地址空间很大，堆和栈并不是两个必然相向增长、最终相遇的连续区域。</p><table><thead><tr><th>区域</th><th>典型内容</th><th>常见权限</th><th>生命周期与管理者</th></tr></thead><tbody><tr><td>代码区 <code>.text</code></td><td>编译生成的机器指令</td><td>读、执行</td><td>随可执行文件或共享库映射存在</td></tr><tr><td>只读数据区 <code>.rodata</code></td><td>字符串字面量、部分常量和常量表</td><td>只读</td><td>通常随所属模块存在</td></tr><tr><td>已初始化数据区 <code>.data</code></td><td>带非零常量初值的全局变量、静态变量</td><td>读、写</td><td>主程序中的对象通常具有程序级存储期</td></tr><tr><td>零初始化区 <code>.bss</code></td><td>未显式初始化或零初始化的全局、静态变量</td><td>读、写</td><td>与其他静态存储对象相同</td></tr><tr><td>堆及动态分配区域</td><td><code>malloc</code>、<code>new</code> 等分配的对象</td><td>通常读、写</td><td>由分配器和程序管理，或由垃圾回收器管理</td></tr><tr><td>栈</td><td>栈帧、溢出到内存的局部值、部分调用数据</td><td>通常读、写</td><td>每个线程独立使用，由调用过程维护</td></tr><tr><td>内存映射区域</td><td>共享库、映射文件、匿名内存等</td><td>由映射属性决定</td><td>由加载器、运行时或 <code>mmap</code>/<code>munmap</code> 管理</td></tr><tr><td>线程局部存储 TLS</td><td>每个线程独有的静态存储对象</td><td>通常读、写</td><td>与所属线程关联</td></tr></tbody></table><p>这些权限是常见配置。例如，重定位完成后，加载器可以把部分原本可写的数据页改为只读；JIT 编译器也需要专门管理动态生成代码的可写与可执行权限。</p><h2 id="代码区-程序要执行的指令" tabindex="-1"><a class="header-anchor" href="#代码区-程序要执行的指令" aria-hidden="true">#</a> 代码区：程序要执行的指令</h2><p>代码区通常对应 ELF 中的 <code>.text</code> 节，保存编译后的机器指令。调用一个普通函数，主要是按照调用约定准备参数，再将控制流转移到该函数的指令地址，并不会把函数代码复制到栈上。</p><p>代码页通常可读、可执行而不可写，以避免普通数据写入意外破坏指令。同一个可执行文件或共享库的只读代码页，可以由多个进程共享底层物理页，而各进程仍保有独立的虚拟地址映射。</p><p>代码区通常随模块加载而建立，随模块卸载或进程结束而撤销。JIT 生成的指令则可能位于匿名映射中，并不一定属于文件的 <code>.text</code> 节。</p><h2 id="只读数据区-字面量与常量表" tabindex="-1"><a class="header-anchor" href="#只读数据区-字面量与常量表" aria-hidden="true">#</a> 只读数据区：字面量与常量表</h2><p>只读数据区通常对应 <code>.rodata</code> 节，可以保存字符串字面量、查找表以及不需要修改的静态数据。</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">const</span> <span class="token keyword">char</span> <span class="token operator">*</span>message <span class="token operator">=</span> <span class="token string">&quot;hello&quot;</span><span class="token punctuation">;</span>
<span class="token keyword">char</span> buffer<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;hello&quot;</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>如果这两个定义位于文件作用域，<code>message</code> 本身是一个可修改的全局指针，通常放在可写的数据区域；它指向的字符串字面量通常在只读区域。<code>buffer</code> 则是一个可写数组，其各个字符属于数组自身，通常在 <code>.data</code> 中。</p><p>因此，<strong>指针存在哪里，与它指向的对象存在哪里，是两个问题</strong>。试图修改字符串字面量属于未定义行为，常见结果是触发内存保护异常。</p><p><code>const</code> 也不等于“一定存放在 <code>.rodata</code>”。局部 <code>const</code> 对象可能位于栈上、寄存器中，或者被优化掉；某些包含地址且需要重定位的只读对象，也可能先置于可写区域，再由加载器收紧权限。</p><h2 id="已初始化数据区-带初值的可写对象" tabindex="-1"><a class="header-anchor" href="#已初始化数据区-带初值的可写对象" aria-hidden="true">#</a> 已初始化数据区：带初值的可写对象</h2><p><code>.data</code> 通常保存具有静态存储期、带非零常量初值的可写对象，例如：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">int</span> global_count <span class="token operator">=</span> <span class="token number">10</span><span class="token punctuation">;</span>
<span class="token keyword">static</span> <span class="token keyword">int</span> file_count <span class="token operator">=</span> <span class="token number">20</span><span class="token punctuation">;</span>

<span class="token keyword">void</span> <span class="token function">count</span><span class="token punctuation">(</span><span class="token keyword">void</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">static</span> <span class="token keyword">int</span> calls <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span>
    <span class="token operator">++</span>calls<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这些初始值需要记录在可执行文件中，加载时据此建立内存中的初始内容。程序运行后可以修改这些对象，普通私有数据映射中的修改不会直接改写磁盘上的可执行文件。</p><p>函数内的 <code>static</code> 变量也不是普通栈变量。<code>calls</code> 的名字只能在该函数的作用域内使用，但其存储会跨越多次函数调用保留。这里要区分<strong>作用域</strong>与<strong>存储期</strong>：前者决定名字在哪里可见，后者决定存储存在多久。</p><p>C++ 中需要动态初始化的全局或静态对象，不能简单理解为“完整初值都写在 <code>.data</code> 里”。其存储可能先被零初始化，再由启动代码或首次执行到声明处时的初始化代码完成构造。</p><h2 id="零初始化区-bss-为什么节省文件空间" tabindex="-1"><a class="header-anchor" href="#零初始化区-bss-为什么节省文件空间" aria-hidden="true">#</a> 零初始化区：<code>.bss</code> 为什么节省文件空间</h2><p><code>.bss</code> 通常保存没有显式初始化，或者初始化为零的全局变量和静态变量：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">int</span> total<span class="token punctuation">;</span>
<span class="token keyword">static</span> <span class="token keyword">int</span> errors <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token keyword">static</span> <span class="token keyword">char</span> workspace<span class="token punctuation">[</span><span class="token number">1024</span> <span class="token operator">*</span> <span class="token number">1024</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这类对象在程序开始使用前会被零初始化。为了表示一百万个零，没有必要在可执行文件里真的写入一百万个零字节。ELF 的 <code>.bss</code> 通常采用 <code>SHT_NOBITS</code> 类型，记录大小和属性，但不保存对应的数据字节；加载段的内存大小可以大于其文件内容大小，由加载过程提供额外的零填充空间。</p><p>因此，较大的 <code>.bss</code> 会增加运行时所需的虚拟内存，却不会等量增加可执行文件大小。物理页通常按需建立，声明一个大数组也不意味着启动时立即独占同等大小的物理内存。</p><p>这里的零初始化规则不适用于普通未初始化的自动局部变量。读取这类局部变量的未确定值可能导致未定义行为，不能假定它们也是零。</p><h2 id="堆-由程序控制生命周期的动态对象" tabindex="-1"><a class="header-anchor" href="#堆-由程序控制生命周期的动态对象" aria-hidden="true">#</a> 堆：由程序控制生命周期的动态对象</h2><p>当对象大小在运行时才确定，或者对象需要在创建它的函数返回后继续存在时，通常会使用动态分配。</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">int</span> <span class="token operator">*</span><span class="token function">make_value</span><span class="token punctuation">(</span><span class="token keyword">void</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">int</span> <span class="token operator">*</span>p <span class="token operator">=</span> <span class="token function">malloc</span><span class="token punctuation">(</span><span class="token keyword">sizeof</span> <span class="token operator">*</span>p<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">/* 需要包含 &lt;stdlib.h&gt; */</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>p <span class="token operator">!=</span> <span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token operator">*</span>p <span class="token operator">=</span> <span class="token number">42</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">return</span> p<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>局部指针变量 <code>p</code> 通常位于寄存器或栈上；它指向的 <code>int</code> 位于动态分配区域。函数返回后，局部变量的生命周期结束，但分配的对象仍然存在，调用者最终需要用 <code>free</code> 释放它。</p><p>从语言和分配器的角度，这些对象通常统称为“堆对象”。但在 Linux 的内存映射中，它们不一定全部位于标记为 <code>[heap]</code> 的区域：分配器可以扩展传统 <code>brk</code> 堆，也可以通过 <code>mmap</code> 获得独立的匿名映射，再把内存切分成小块。</p><p>分配器往往会复用空闲块，所以每次 <code>malloc</code> 不一定执行系统调用，每次 <code>free</code> 也不一定立即把内存归还给操作系统。具体策略由分配器实现、配置和运行状态决定，不能用一个固定的申请大小概括所有情况。</p>`,31),v=n("code",null,"new",-1),m=n("code",null,"delete",-1),h=n("h2",{id:"栈-组织函数调用的临时存储",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#栈-组织函数调用的临时存储","aria-hidden":"true"},"#"),s(" 栈：组织函数调用的临时存储")],-1),b=n("p",null,"每个线程通常都有自己的栈。函数调用时，编译器根据调用约定生成代码，在需要时调整栈指针，建立栈帧；返回时恢复调用者的状态。这个过程通常不需要操作系统为每次调用单独分配一块内存。",-1),y=n("p",null,"栈帧可能包含局部数组、无法一直保存在寄存器中的临时值、保存的寄存器、部分参数，以及返回所需的信息。具体内容取决于处理器和 ABI：例如，x86 的调用指令会把返回地址压栈，而另一些体系结构会先将返回地址放入链接寄存器。",-1),g=n("p",null,[n("strong",null,"局部变量、参数和返回值并不一定存放在栈上"),s("。它们可能通过寄存器传递或被优化掉，叶子函数甚至可能不需要常规栈帧。返回值的传递位置也由调用约定决定。")],-1),_=n("p",null,"普通自动局部对象的生命周期通常在离开所属作用域时结束。返回它的地址，或者把该地址保存到外部供以后使用，会留下悬空指针。递归过深或局部数组过大，则可能超过栈的限制，引发栈溢出。",-1),f=t(`<h2 id="内存映射区域-文件、共享库和匿名内存" tabindex="-1"><a class="header-anchor" href="#内存映射区域-文件、共享库和匿名内存" aria-hidden="true">#</a> 内存映射区域：文件、共享库和匿名内存</h2><p>Linux 的 <code>mmap</code> 可以在进程地址空间中建立新的映射。映射区域并不等同于“共享内存”，它有多种用途：</p><ul><li><strong>文件映射</strong>：把文件内容映射到虚拟地址，通过内存访问读写对应内容。</li><li><strong>共享库映射</strong>：动态加载器分别映射共享库的代码、只读数据和可写数据，按需设置权限。</li><li><strong>匿名映射</strong>：没有普通文件作为后备存储，可用于动态分配、线程栈及运行时内部数据等。</li><li><strong>共享内存</strong>：多个进程映射同一共享对象，访问同一份底层数据，用于进程间通信。</li></ul><p><code>MAP_PRIVATE</code> 建立私有映射，写入通常通过**写时复制（Copy-on-Write）**形成私有页面，不会把这些修改写回原文件。<code>MAP_SHARED</code> 则允许对同一映射对象的修改被其他相应映射观察到；文件回写时机是另一个问题，不能把普通内存写入等同于数据已经持久化到磁盘。</p><p>共享内存只解决“访问同一份数据”的问题，并不自动解决并发问题。多个进程同时读写时，仍然需要适当的同步机制。</p><p>映射通常通过 <code>munmap</code> 撤销，或在进程退出时由操作系统清理。解除映射后，原来指向该范围的指针也就失效了。</p><h2 id="线程局部存储-每个线程一份的变量" tabindex="-1"><a class="header-anchor" href="#线程局部存储-每个线程一份的变量" aria-hidden="true">#</a> 线程局部存储：每个线程一份的变量</h2><p>全局变量通常由进程内的线程共享，但有些状态需要每个线程独立保存。C11 的 <code>_Thread_local</code> 和 C++ 的 <code>thread_local</code> 就用于表达这类需求。</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">_Thread_local</span> <span class="token keyword">int</span> thread_error<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>每个线程访问 <code>thread_error</code> 时，得到的是自己的实例。它既不是所有线程共用的一份普通全局变量，也不是每次函数调用重新创建的自动局部变量。</p><p>ELF 常用 <code>.tdata</code> 和 <code>.tbss</code> 描述 TLS 的初始化模板及零初始化部分，由加载器和线程运行时为各线程建立实际存储。TLS 不必表现为地址图中一个独立、连续的大区域；访问它还需要编译器生成符合平台 TLS 模型的寻址代码。</p><h2 id="内核空间-受权限保护的系统内存" tabindex="-1"><a class="header-anchor" href="#内核空间-受权限保护的系统内存" aria-hidden="true">#</a> 内核空间：受权限保护的系统内存</h2><p>内核代码、内核数据和设备相关映射由操作系统管理。用户程序不能像访问自己的数组一样直接读写内核地址，而是通过系统调用请求内核执行文件操作、创建映射等服务。</p><p>传统布局图经常在进程地址空间顶部画出内核区域，用来表示用户态与内核态的边界。但这并不意味着每个进程都有一份完整的内核副本，也不意味着用户态页表始终映射了整个内核。启用 KPTI 等机制时，用户态与内核态可以使用不同的页表映射范围。</p><p>因此，内核空间应理解为受特权级保护的系统地址范围，不能与用户程序的代码、数据、堆、栈视为同样可访问的内存。</p><h2 id="虚拟地址如何对应物理内存" tabindex="-1"><a class="header-anchor" href="#虚拟地址如何对应物理内存" aria-hidden="true">#</a> 虚拟地址如何对应物理内存</h2><p>操作系统通过页表描述虚拟页到物理页的映射，以及页面的读、写、执行和访问级别等权限。现代平台通常使用多级页表，处理器的 MMU 完成地址翻译，TLB 缓存近期使用的翻译结果。</p><p>一次虚拟内存访问不一定需要完整遍历页表：TLB 命中时可以快速获得映射。但 TLB 未命中会增加地址翻译开销；如果页面尚未建立映射或访问违反权限，还可能产生缺页异常（page fault）。</p><p>缺页异常不一定表示程序出错。操作系统可能按需分配零页、从文件载入页面，或处理写时复制后继续执行；非法地址或权限错误才可能导致进程收到 <code>SIGSEGV</code> 等信号。因此，<strong>虚拟地址空间大小、已映射大小和实际驻留的物理内存大小不是同一个指标</strong>。</p><h2 id="实验-观察变量、elf-节与进程映射" tabindex="-1"><a class="header-anchor" href="#实验-观察变量、elf-节与进程映射" aria-hidden="true">#</a> 实验：观察变量、ELF 节与进程映射</h2><p>下面的程序把几类对象放到一起。保存为 <code>layout.c</code>，在 Linux 上使用 GCC 编译：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;stdio.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;stdlib.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;unistd.h&gt;</span></span>

<span class="token keyword">int</span> initialized <span class="token operator">=</span> <span class="token number">42</span><span class="token punctuation">;</span>
<span class="token keyword">int</span> zero_initialized<span class="token punctuation">;</span>
<span class="token keyword">static</span> <span class="token keyword">const</span> <span class="token keyword">char</span> readonly_text<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;read only&quot;</span><span class="token punctuation">;</span>
<span class="token keyword">_Thread_local</span> <span class="token keyword">int</span> thread_value <span class="token operator">=</span> <span class="token number">7</span><span class="token punctuation">;</span>

<span class="token keyword">int</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token keyword">void</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">int</span> local <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span>
    <span class="token keyword">static</span> <span class="token keyword">int</span> static_local <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span>
    <span class="token keyword">int</span> <span class="token operator">*</span>dynamic <span class="token operator">=</span> <span class="token function">malloc</span><span class="token punctuation">(</span><span class="token keyword">sizeof</span> <span class="token operator">*</span>dynamic<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>dynamic <span class="token operator">==</span> <span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> EXIT_FAILURE<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token operator">*</span>dynamic <span class="token operator">=</span> <span class="token number">3</span><span class="token punctuation">;</span>

    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;pid               = %ld\\n&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword">long</span><span class="token punctuation">)</span><span class="token function">getpid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;initialized       = %p\\n&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword">void</span> <span class="token operator">*</span><span class="token punctuation">)</span><span class="token operator">&amp;</span>initialized<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;zero_initialized  = %p\\n&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword">void</span> <span class="token operator">*</span><span class="token punctuation">)</span><span class="token operator">&amp;</span>zero_initialized<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;readonly_text     = %p\\n&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword">void</span> <span class="token operator">*</span><span class="token punctuation">)</span>readonly_text<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;static_local      = %p\\n&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword">void</span> <span class="token operator">*</span><span class="token punctuation">)</span><span class="token operator">&amp;</span>static_local<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;thread_value      = %p\\n&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword">void</span> <span class="token operator">*</span><span class="token punctuation">)</span><span class="token operator">&amp;</span>thread_value<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;local             = %p\\n&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword">void</span> <span class="token operator">*</span><span class="token punctuation">)</span><span class="token operator">&amp;</span>local<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;dynamic (pointer) = %p\\n&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword">void</span> <span class="token operator">*</span><span class="token punctuation">)</span><span class="token operator">&amp;</span>dynamic<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;dynamic (object)  = %p\\n&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword">void</span> <span class="token operator">*</span><span class="token punctuation">)</span>dynamic<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">puts</span><span class="token punctuation">(</span><span class="token string">&quot;Press Enter to exit.&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">(</span><span class="token keyword">void</span><span class="token punctuation">)</span><span class="token function">getchar</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token function">free</span><span class="token punctuation">(</span>dynamic<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> EXIT_SUCCESS<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>gcc <span class="token parameter variable">-std</span><span class="token operator">=</span>c11 <span class="token parameter variable">-O0</span> <span class="token parameter variable">-g</span> <span class="token parameter variable">-Wall</span> <span class="token parameter variable">-Wextra</span> layout.c <span class="token parameter variable">-o</span> layout
readelf <span class="token parameter variable">-S</span> layout   <span class="token comment"># 查看节表：.text、.rodata、.data、.bss、TLS 等</span>
readelf <span class="token parameter variable">-l</span> layout   <span class="token comment"># 查看程序头，以及节与加载段的对应关系</span>
size layout        <span class="token comment"># 查看 text、data、bss 等大小的汇总</span>
./layout
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>程序等待输入时，在另一个终端执行 <code>cat /proc/&lt;pid&gt;/maps</code>，把 <code>&lt;pid&gt;</code> 替换为程序输出的进程号，就可以对照各地址所属的映射。权限字段中的 <code>r</code>、<code>w</code>、<code>x</code> 分别表示读、写、执行，<code>p</code>、<code>s</code> 分别表示私有与共享映射。</p><p>观察时可以重点比较：</p><ol><li><code>initialized</code> 与 <code>zero_initialized</code> 对应的 ELF 节不同，但可能出现在同一个可写映射中，不能只靠 <code>maps</code> 判断节边界。</li><li><code>static_local</code> 不随函数的普通局部变量一起放在栈上；<code>dynamic</code> 指针自身与它指向的对象也通常位于不同区域。</li><li><code>readonly_text</code> 所在页面通常不可写；TLS 变量有自己的寻址方式，不能仅凭它靠近哪个地址就认定它属于普通堆或栈。</li><li>多次运行时，ASLR 可能使地址变化。编译优化、链接选项和分配器实现也会影响观察结果，示例中的地址关系不应成为程序的依赖。</li></ol><p>对于编译器实现，这些区别最终会落实为不同的代码生成方式：函数生成指令，全局和静态对象生成数据及初始化代码，自动局部值参与寄存器分配或栈帧布局，动态对象通过运行时分配器创建，线程局部对象则使用 TLS 寻址。理解对象的存储期与访问方式，才能正确选择它在运行时的表示。</p>`,27);function w(x,E){const c=o("RuntimeMemoryLayout"),e=o("RouterLink");return i(),d("div",null,[u,a(c),k,n("p",null,[s("常见错误包括忘记释放造成的内存泄漏、释放后继续访问、重复释放，以及越过分配范围读写。C++ 中的 "),v,s("/"),m,s(" 还涉及对象构造与析构，应配对使用对应的分配和释放方式。更多分配细节见"),a(e,{to:"/%E8%BF%90%E8%A1%8C%E6%97%B6%E7%8E%AF%E5%A2%83/1.%E5%86%85%E5%AD%98%E5%B8%83%E5%B1%80/(3)%E5%A0%86.html"},{default:p(()=>[s("堆")]),_:1}),s("。")]),h,b,y,g,_,n("p",null,[s("在常见的 x86/x86-64 Linux 环境中，栈向低地址增长，但这不是所有平台的统一规定。线程栈常配有不可访问的保护页，用于帮助发现越界。不同线程的栈虽然分别使用，却仍处于同一进程地址空间，并没有进程级隔离。具体调用过程见"),a(e,{to:"/%E8%BF%90%E8%A1%8C%E6%97%B6%E7%8E%AF%E5%A2%83/1.%E5%86%85%E5%AD%98%E5%B8%83%E5%B1%80/(2)%E6%A0%88%E5%B8%A7.html"},{default:p(()=>[s("栈帧")]),_:1}),s("。")]),f])}const T=l(r,[["render",w],["__file","(1)运行时内存布局.html.vue"]]);export{T as default};
